package auth

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"strings"
	"testing"
)

// testdata/wphash.json is generated by dev/golden/auth.php with WordPress'
// own hashing functions (make golden).
func TestVerifyWordPressHashes(t *testing.T) {
	data, err := os.ReadFile("testdata/wphash.json")
	if err != nil {
		t.Fatal(err)
	}
	var vectors []struct{ Password, Scheme, Hash string }
	if err := json.Unmarshal(data, &vectors); err != nil {
		t.Fatal(err)
	}
	ctx := context.Background()
	schemes := map[string]bool{}
	for _, v := range vectors {
		schemes[v.Scheme] = true
		ok, rehash := VerifyPassword(ctx, v.Password, v.Hash)
		if !ok || !rehash {
			t.Errorf("%s %q: ok=%v rehash=%v", v.Scheme, v.Password, ok, rehash)
		}
		// Plain bcrypt ignores everything after 72 bytes (as in PHP).
		if v.Scheme == "bcrypt" && len(v.Password) >= 72 {
			continue
		}
		if ok, _ := VerifyPassword(ctx, v.Password+"x", v.Hash); ok {
			t.Errorf("%s %q: wrong password accepted", v.Scheme, v.Password)
		}
	}
	for _, s := range []string{"wp", "phpass", "bcrypt", "md5"} {
		if !schemes[s] {
			t.Errorf("no vectors for %s", s)
		}
	}
}

func TestArgon2RoundTrip(t *testing.T) {
	ctx := context.Background()
	h, err := HashPassword(ctx, "correct horse battery staple")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(h, "$argon2id$v=19$m=65536,t=3,p=1$") {
		t.Errorf("hash = %s", h)
	}
	if ok, rehash := VerifyPassword(ctx, "correct horse battery staple", h); !ok || rehash {
		t.Errorf("verify: ok=%v rehash=%v", ok, rehash)
	}
	if ok, _ := VerifyPassword(ctx, "correct horse battery stapl", h); ok {
		t.Error("wrong password accepted")
	}
	// Weaker parameters verify but ask for a rehash.
	old := strings.Replace(h, "m=65536,t=3", "m=65536,t=2", 1)
	if ok, _ := VerifyPassword(ctx, "correct horse battery staple", old); ok {
		t.Error("tampered parameters must not verify with the same key")
	}
	// Absurd parameters are refused without running argon2.
	if ok, _ := VerifyPassword(ctx, "x", "$argon2id$v=19$m=99999999,t=3,p=1$AAAA$AAAA"); ok {
		t.Error("absurd parameters accepted")
	}
	if ok, _ := VerifyPassword(ctx, strings.Repeat("a", MaxPasswordBytes+1), h); ok {
		t.Error("overlong password accepted")
	}
	if ok, _ := VerifyPassword(ctx, "", ""); ok {
		t.Error("empty hash accepted")
	}
}

func TestPasswordPolicy(t *testing.T) {
	for _, c := range []struct {
		pw string
		ok bool
	}{
		{"short", false},
		{"elevenchars", false},
		{"administrator", false},       // login
		{"admin@example.org", false},   // email
		{"qwertyuiopasdfghjkl", false}, // common
		{"PASSWORD1234", false},        // common, case-insensitive
		{"correct horse battery staple", true},
		{"ünïcödé-pässwörd", true},
		{strings.Repeat("x", 257), false},
	} {
		err := CheckPasswordPolicy(c.pw, "administrator", "admin@example.org")
		var weak *ErrWeakPassword
		if (err == nil) != c.ok || (err != nil && !errors.As(err, &weak)) {
			t.Errorf("%q: %v", c.pw, err)
		}
	}
}
